import unittest
from order_ids import normalize_order_id

class OrderIdTests(unittest.TestCase):
    def test_leading_zero(self):
        self.assertEqual(normalize_order_id("00123"), "00123")
    def test_alphanumeric(self):
        self.assertEqual(normalize_order_id("A007"), "A007")
    def test_plain(self):
        self.assertEqual(normalize_order_id("123"), "123")

