import unittest
from customer_ids import normalize_customer_id

class CustomerTests(unittest.TestCase):
    def test_leading_zero(self):
        self.assertEqual(normalize_customer_id("00042"), "00042")
    def test_alphanumeric(self):
        self.assertEqual(normalize_customer_id("C042"), "C042")
    def test_whitespace(self):
        self.assertEqual(normalize_customer_id(" 00042 "), " 00042 ")
    def test_empty(self):
        with self.assertRaises(ValueError): normalize_customer_id("")
